-- Runs on every API start. Upserts, so editing a row here updates the DB.
-- MLAs: 2023 Karnataka Assembly election. MPs: 2024 Lok Sabha election.
-- Re-check after any by-election, resignation or defection.
ON CONFLICT (role, constituency) DO UPDATE SET
  name = EXCLUDED.name,
  party = EXCLUDED.party,
  term = EXCLUDED.term,
  note = EXCLUDED.note,
  source_url = EXCLUDED.source_url,
  verified_at = EXCLUDED.verified_at;
